"""A tiny synthetic project for trying CellQuorum without any data of your own.

``cellquorum demo`` writes this into a folder: a small ``.h5ad`` (120 cells, six samples from
three donors, two conditions) and a config that runs the CPU-only part of the pipeline. It is
only meant to show the shape of a run. The numbers are random and mean nothing biologically.
"""

from __future__ import annotations

from pathlib import Path

import anndata as ad
import numpy as np
import pandas as pd
import yaml
from scipy import sparse

N_CELLS = 120
N_GENES = 80
SEED = 71

CONFIG_HEADER = """\
# Generated by `cellquorum demo`. A small CPU-only run on synthetic data.
#
# To analyse your own data, copy this file and change three things:
#   input.h5ad      path to your .h5ad file (raw counts in a layer named `counts`)
#   cohort / design the obs columns that hold sample, donor and condition, and which
#                   condition is the case and which the control
#   stages          switch on the analyses you want (see docs/guide/configuration.md)
#
"""


def write_demo_project(directory: str | Path) -> tuple[Path, Path]:
    """Write the demo data and config into ``directory``; return their paths.

    Args:
        directory: Folder to write into. It is created if it does not exist.

    Returns:
        ``(data_path, config_path)``. The config points at the data by absolute path.
    """
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    data_path = (directory / "input.h5ad").resolve()
    config_path = directory / "config.yaml"
    _demo_dataset().write_h5ad(data_path)
    config_path.write_text(CONFIG_HEADER + yaml.safe_dump(_demo_config(data_path), sort_keys=False))
    return data_path, config_path


def _demo_dataset() -> ad.AnnData:
    rng = np.random.default_rng(SEED)
    counts = rng.poisson(3, size=(N_CELLS, N_GENES)).astype(np.float32)
    counts[:, :2] = rng.poisson(0.15, size=(N_CELLS, 2))  # two mitochondrial-like genes
    obs = pd.DataFrame(
        {
            "sample": np.repeat([f"s{i}" for i in range(6)], 20),
            "donor": np.repeat(["d1", "d1", "d2", "d2", "d3", "d3"], 20),
            "condition": np.tile(np.repeat(["control", "treated"], 20), 3),
        },
        index=[f"cell{i}" for i in range(N_CELLS)],
    )
    genes = ["MT-CO1", "MT-ND1"] + [f"G{i}" for i in range(N_GENES - 2)]
    data = ad.AnnData(sparse.csr_matrix(counts), obs=obs, var=pd.DataFrame(index=genes))
    data.layers["counts"] = data.X.copy()
    return data


def _demo_config(data_path: Path) -> dict:
    return {
        "project": {"name": "cellquorum_demo"},
        "input": {"h5ad": str(data_path), "counts_layer": "counts"},
        "compute": {"backend": "cpu", "prefer_gpu": False},
        "r": {"enabled": False},
        "run": {"random_seed": 7, "verbose": False},
        "cohort": {
            "sample_key": "sample",
            "donor_key": "donor",
            "condition_key": "condition",
            "condition_levels": ["control", "treated"],
        },
        "design": {
            "donor_col": "donor",
            "condition_col": "condition",
            "case": "treated",
            "control": "control",
            "paired": True,
        },
        "stages": _stage_flags(),
        "qc_evidence": {
            "metrics": {"layer": "counts", "percent_top": [20]},
            "floors": {"min_genes_per_cell": 20, "min_cells_per_gene": 1},
            "doublets": {"enabled": False},
            "graded": {"archetype_audit": False},
            "outputs": {"write_figures": False},
        },
        "preprocessing": {
            "normalization": {"input_layer": "counts", "recipe": "cellquorum_log1p_cp10k_v1"}
        },
        "dimensionality": {"input_layer": "cellquorum_normalized", "n_pcs": 5, "max_pcs": 5},
        "clustering": {"method": "leiden", "use_rep": "X_pca"},
        "population_identity": {"cluster_key": "leiden", "write_figures": False},
        "embeddings": {
            "use_rep": "X_pca",
            "embeddings": ["umap"],
            "color_by": ["leiden"],
            "figure_formats": ["png", "pdf"],
            "dpi": 150,
        },
        "report": {"enabled": True, "html": True, "markdown": True},
    }


def _stage_flags() -> dict[str, bool]:
    from cellquorum.config.models import StageSelectionConfig

    enabled = {
        "qc_evidence",
        "preprocessing",
        "dimensionality",
        "clustering",
        "population_identity",
        "embeddings",
    }
    return {name: name in enabled for name in StageSelectionConfig.model_fields}


__all__ = ["write_demo_project"]
